// App.jsx
import { useState, useEffect } from 'react';
import './App.css';
import './styles.css';
import './upgrades.css'; // ← new: must stay AFTER styles.css so it can extend it
import Navbar from '../components/navbar';
import CustomCursor from './cursor';
import Home from './Home';
import About from './About';
import Projects from './Projects';
import Skills from './Skills';
import Contact from './Contact';

function App() {
  const [activePage, setActivePage] = useState('Home');
  const [showBackToTop, setShowBackToTop] = useState(false);

  // Scroll to top when page changes
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, [activePage]);

  // Show/hide back-to-top button
  useEffect(() => {
    const handleScroll = () => setShowBackToTop(window.scrollY > 300);
    handleScroll();
    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const renderPage = () => {
    switch (activePage) {
      case 'About':    return <About />;
      case 'Projects': return <Projects />;
      case 'Skills':   return <Skills />;
      case 'Contact':  return <Contact />;
      case 'Home':
      default:         return <Home setActivePage={setActivePage} />;
    }
  };

  return (
    <div className="portfolio-wrapper">
      <CustomCursor />

      {/* Ambient background blobs */}
      <div className="blob blob-1" />
      <div className="blob blob-2" />
      <div className="blob blob-3" />

      <Navbar activePage={activePage} setActivePage={setActivePage} />

      {/* key forces a fresh mount per page, so entrance animations replay */}
      <div className="page-content" key={activePage}>
        {renderPage()}
      </div>

      <button
        className={`back-to-top ${showBackToTop ? 'show' : ''}`}
        onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
        aria-label="Back to top"
      >
        <span className="back-to-top-arrow">↑</span>
      </button>
    </div>
  );
}

export default App;
